INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7432108, 1174505, 181814, '<td valign="top">Now this is some creativity on display, if this doesn''t finish in first place it will be a shame. You get a perfect 10 from me, it is super good in my opinion, great pose great lighting and exposure and excellent post-processing, this is what I call thinking outside the box. Good luck to you.</td>', 'Now this is some creativity on display, if this doesn''t finish in first place it will be a shame. You get a perfect 10 from me, it is super good in my opinion, great pose great lighting and exposure and excellent post-processing, this is what I call thinking outside the box. Good luck to you.', '2016-01-27 00:30:33.000000', NULL, 1),
(7432109, 1174494, 181814, '<td valign="top">This is really nice, I like the composition, the background you chose and the color toning. The focus, exposure and creativity are all extremely well done. I like the shadow of the rope on the left and what looks like the Devil''s shadow in the lower right corner. This should finish right near the top when it is all said and done.</td>', 'This is really nice, I like the composition, the background you chose and the color toning. The focus, exposure and creativity are all extremely well done. I like the shadow of the rope on the left and what looks like the Devil''s shadow in the lower right corner. This should finish right near the top when it is all said and done.', '2016-01-27 00:37:08.000000', NULL, 1),
(7432110, 1174712, 181814, '<td valign="top">There are some great entries in this contest and this is one of the greats. It is a unique use of rope and fits this contest to a T, the composition, focus, exposure and creativity are all well done. I think you will do well in this contest for sure.</td>', 'There are some great entries in this contest and this is one of the greats. It is a unique use of rope and fits this contest to a T, the composition, focus, exposure and creativity are all well done. I think you will do well in this contest for sure.', '2016-01-27 00:41:40.000000', NULL, 1),
(7432239, 1174541, 181814, '<td valign="top">Very generic piece of rope with good focus and nicely exposed.</td>', 'Very generic piece of rope with good focus and nicely exposed.', '2016-01-27 08:42:49.000000', NULL, 1),
(7432242, 1174732, 181814, '<td valign="top">Don''t be so mad you''re not over the hill yet :-) I like the idea it is very well executed, the focus is great, I like the background and the lighting. I wish the loop of the rope wasn''t cut off at the bottom and I don''t think the thing you are wearing on your head does much for the overall success of the photograph because I keep looking at it rather than the subject. Very nicely done.</td>', 'Don''t be so mad you''re not over the hill yet :-) I like the idea it is very well executed, the focus is great, I like the background and the lighting. I wish the loop of the rope wasn''t cut off at the bottom and I don''t think the thing you are wearing on your head does much for the overall success of the photograph because I keep looking at it rather than the subject. Very nicely done.', '2016-01-27 08:47:04.000000', NULL, 1),
(7432247, 1174622, 181814, '<td valign="top">Very simplistic but very appealing.</td>', 'Very simplistic but very appealing.', '2016-01-27 09:09:07.000000', NULL, 1),
(7432248, 1174671, 181814, '<td valign="top">Why did you kidnap the rubber duck, what is the ransom? Very creative and nice set-up.</td>', 'Why did you kidnap the rubber duck, what is the ransom? Very creative and nice set-up.', '2016-01-27 09:13:27.000000', NULL, 1),
(7432251, 1174486, 181814, '<td valign="top">I think you tried to sharpen this too much which created a lot of noise and got rid of the rope texture in the process.I think it would look much better if it looked more natural.</td>', 'I think you tried to sharpen this too much which created a lot of noise and got rid of the rope texture in the process.I think it would look much better if it looked more natural.', '2016-01-27 09:17:06.000000', NULL, 1),
(7432256, 1174707, 181814, '<td valign="top">This is a very cute little dog munching on it''s piece of rope which is well defined, the exposure is great and it is very well focused and composed, I really like how it turned out, nice work.</td>', 'This is a very cute little dog munching on it''s piece of rope which is well defined, the exposure is great and it is very well focused and composed, I really like how it turned out, nice work.', '2016-01-27 09:36:44.000000', NULL, 1),
(7432325, 1174564, 86447, '<td valign="top">Oh... nicely done!</td>', 'Oh... nicely done!', '2016-01-27 11:31:35.000000', NULL, 1),
(7432326, 1174505, 86447, '<td valign="top">WOw!  THat''s a lot of rope!  I love all of it... except for the stuff lain on the head.<br/> <br/>The rest... magnificent!</td>', 'WOw!  THat''s a lot of rope!  I love all of it... except for the stuff lain on the head. The rest... magnificent!', '2016-01-27 11:32:23.000000', NULL, 1),
(7432327, 1174732, 86447, '<td valign="top">Oh... don''t be sad!  You look great!</td>', 'Oh... don''t be sad!  You look great!', '2016-01-27 11:33:38.000000', NULL, 1),
(7432328, 1174707, 86447, '<td valign="top">Awww... adorable.</td>', 'Awww... adorable.', '2016-01-27 11:34:28.000000', NULL, 1),
(7432329, 1174671, 86447, '<td valign="top">Poor little ducky.  <br/>He''s already been well shot... and now he''s to hang?!   Poor little ducky.</td>', 'Poor little ducky.  He''s already been well shot... and now he''s to hang?!   Poor little ducky.', '2016-01-27 11:35:37.000000', NULL, 1),
(7432331, 1174715, 86447, '<td valign="top">Oh... lovely!</td>', 'Oh... lovely!', '2016-01-27 11:36:31.000000', NULL, 1),
(7432334, 1174553, 86447, '<td valign="top">Simple and interesting.   Well done.</td>', 'Simple and interesting.   Well done.', '2016-01-27 11:37:12.000000', NULL, 1),
(7432337, 1174720, 86447, '<td valign="top">Busy.   I like it.</td>', 'Busy.   I like it.', '2016-01-27 11:37:41.000000', NULL, 1),
(7432338, 1174693, 86447, '<td valign="top">I wish the rope were in focus instead of the wall.</td>', 'I wish the rope were in focus instead of the wall.', '2016-01-27 11:38:05.000000', NULL, 1),
(7432339, 1174554, 86447, '<td valign="top">Great detail.</td>', 'Great detail.', '2016-01-27 11:38:16.000000', NULL, 1),
(7432365, 1174505, 114969, '<td valign="top">Great, great entry. The best of the challenge by a large margin. I really love the concept, and the tones are just perfect.</td>', 'Great, great entry. The best of the challenge by a large margin. I really love the concept, and the tones are just perfect.', '2016-01-27 12:39:17.000000', NULL, 1),
(7432434, 1174707, 39560, '<td valign="top">clip that dogs nails</td>', 'clip that dogs nails', '2016-01-27 17:11:50.000000', NULL, 1),
(7432463, 1174706, 181814, '<td valign="top">I suppose you could call that a rope, it would look better if it were in focus and maybe composed diagonally, it also looks a little underexposed.</td>', 'I suppose you could call that a rope, it would look better if it were in focus and maybe composed diagonally, it also looks a little underexposed.', '2016-01-27 19:08:40.000000', NULL, 1),
(7432465, 1174693, 181814, '<td valign="top">I think the focus is very soft and I really don''t see a rope. I do see a string of some sort but it really isn''t composed to be the main subject in this photograph. I also think it is a little over exposed and needs more contrast.</td>', 'I think the focus is very soft and I really don''t see a rope. I do see a string of some sort but it really isn''t composed to be the main subject in this photograph. I also think it is a little over exposed and needs more contrast.', '2016-01-27 19:12:33.000000', NULL, 1),
(7432466, 1174730, 181814, '<td valign="top">I think this could be good if it were in focus and with not as much noise within/throughout the photograph.I also think the composition could be much better.</td>', 'I think this could be good if it were in focus and with not as much noise within/throughout the photograph.I also think the composition could be much better.', '2016-01-27 19:14:13.000000', NULL, 1),
(7432468, 1174694, 181814, '<td valign="top">This photograph does not display a rope as the subject as far as I can determine. The overall photograph is rather soft and over exposed.The focus and composition could be much better.</td>', 'This photograph does not display a rope as the subject as far as I can determine. The overall photograph is rather soft and over exposed.The focus and composition could be much better.', '2016-01-27 19:19:22.000000', NULL, 1),
(7432469, 1174654, 181814, '<td valign="top">I wish more of the rope were in focus and maybe a tighter crop would look better, the white open area on the right and the yellow portion on the right side is a little distracting.</td>', 'I wish more of the rope were in focus and maybe a tighter crop would look better, the white open area on the right and the yellow portion on the right side is a little distracting.', '2016-01-27 19:21:35.000000', NULL, 1),
(7432470, 1174716, 181814, '<td valign="top">I really like the depth of field and the water drop in the pond, I just wish the rope were in better focus.</td>', 'I really like the depth of field and the water drop in the pond, I just wish the rope were in better focus.', '2016-01-27 19:22:37.000000', NULL, 1),
(7432472, 1174477, 181814, '<td valign="top">The photograph is under exposed in my opinion, and I think the composition does not  really show the rope as the subject matter. I do like the texture and focus of the rope with the snow on it maybe a tighter vertical or diagonal crop would have helped out.</td>', 'The photograph is under exposed in my opinion, and I think the composition does not  really show the rope as the subject matter. I do like the texture and focus of the rope with the snow on it maybe a tighter vertical or diagonal crop would have helped out.', '2016-01-27 19:27:46.000000', NULL, 1),
(7432474, 1174692, 181814, '<td valign="top">I think that a lager piece of rope rather than twine composed tighter would have helped out. I see a lot of dust spots that could be edited out alswo to improve the overall appearance of the photograph.</td>', 'I think that a lager piece of rope rather than twine composed tighter would have helped out. I see a lot of dust spots that could be edited out alswo to improve the overall appearance of the photograph.', '2016-01-27 19:30:40.000000', NULL, 1),
(7432475, 1174667, 181814, '<td valign="top">I like your cute little model! I think the light is a little harsh and I like the rope on display in its mouth.</td>', 'I like your cute little model! I think the light is a little harsh and I like the rope on display in its mouth.', '2016-01-27 19:32:44.000000', NULL, 1),
(7432477, 1174723, 181814, '<td valign="top">I can see the rope but it does not appear to be the main subject, I I think the photograph is rather busy and would be much better with a tighter crop. The lighting is harsh in spots throughout.</td>', 'I can see the rope but it does not appear to be the main subject, I I think the photograph is rather busy and would be much better with a tighter crop. The lighting is harsh in spots throughout.', '2016-01-27 19:35:18.000000', NULL, 1),
(7432478, 1174564, 181814, '<td valign="top">I think in my opinion a diagonal composition would look better and I would like to be able to see all the fibers/textures of the rope so in my opinion I really don''t like the high-key look.I do like the knot/.</td>', 'I think in my opinion a diagonal composition would look better and I would like to be able to see all the fibers/textures of the rope so in my opinion I really don''t like the high-key look.I do like the knot/.', '2016-01-27 19:37:55.000000', NULL, 1),
(7432482, 1174701, 181814, '<td valign="top">The right side is blown out a bit and the left side is underexposed making parts of the rope hard to see, also I would like to see the focus on the rope much better, it is mostly out of focus/soft.</td>', 'The right side is blown out a bit and the left side is underexposed making parts of the rope hard to see, also I would like to see the focus on the rope much better, it is mostly out of focus/soft.', '2016-01-27 19:51:38.000000', NULL, 1),
(7432484, 1174599, 181814, '<td valign="top">Very nice composition and depth of field.</td>', 'Very nice composition and depth of field.', '2016-01-27 19:56:28.000000', NULL, 1),
(7432485, 1174718, 181814, '<td valign="top">Very nice photograph.</td>', 'Very nice photograph.', '2016-01-27 19:57:28.000000', NULL, 1),
(7432486, 1174705, 181814, '<td valign="top">Very nice, I really like the reflections of the rope, and the focus and composition are very good.</td>', 'Very nice, I really like the reflections of the rope, and the focus and composition are very good.', '2016-01-27 19:58:27.000000', NULL, 1),
(7432551, 1174635, 45631, '<td valign="top">This is a really great images but the subject is ''rope'' and I want the image to be about the rope and not just some rope in an image.  If you had shot this from the tie up area up to the bow of the boat the story would have been about the rope.</td>', 'This is a really great images but the subject is ''rope'' and I want the image to be about the rope and not just some rope in an image.  If you had shot this from the tie up area up to the bow of the boat the story would have been about the rope.', '2016-01-28 03:05:19.000000', NULL, 1),
(7432588, 1174505, 159196, '<td valign="top">For me, this is the clear winner in the challenge! Nothing comes near it either in creativity or execution. Good luck!</td>', 'For me, this is the clear winner in the challenge! Nothing comes near it either in creativity or execution. Good luck!', '2016-01-28 07:11:27.000000', NULL, 1),
(7432647, 1174539, 181814, '<td valign="top">I think the composition could be better i.e. maybe diagonal or showing an even amount of all the ropes, also the lighting horizontally through the middle is a little harsh, the focus is good.</td>', 'I think the composition could be better i.e. maybe diagonal or showing an even amount of all the ropes, also the lighting horizontally through the middle is a little harsh, the focus is good.', '2016-01-28 13:00:50.000000', NULL, 1),
(7432648, 1174655, 181814, '<td valign="top">I think this would be much better if more of it were in focus. I also think it would look better if some of the white spots on the cushion were edited out and the light colored area in the upper right is a little distracting</td>', 'I think this would be much better if more of it were in focus. I also think it would look better if some of the white spots on the cushion were edited out and the light colored area in the upper right is a little distracting', '2016-01-28 13:03:19.000000', NULL, 1),
(7432649, 1174664, 181814, '<td valign="top">The lighting on areas of the rope are harsh resulting in blown out highlights.</td>', 'The lighting on areas of the rope are harsh resulting in blown out highlights.', '2016-01-28 13:04:52.000000', NULL, 1),
(7432650, 1174714, 181814, '<td valign="top">This photograph may have been more suitable for the silhouette contest. I see the ropes but they are not showing any details and don''t seem to be the main subject.I would like it better if there were more open space at the top above the flag.</td>', 'This photograph may have been more suitable for the silhouette contest. I see the ropes but they are not showing any details and don''t seem to be the main subject.I would like it better if there were more open space at the top above the flag.', '2016-01-28 13:08:01.000000', NULL, 1),
(7432651, 1174704, 181814, '<td valign="top">I can barely see what I suspect is rope with all the moss and vegetation growing on it, to me the main subject seems to be the broad leaf plant growing on it. I also think the overall photograph is under exposed.</td>', 'I can barely see what I suspect is rope with all the moss and vegetation growing on it, to me the main subject seems to be the broad leaf plant growing on it. I also think the overall photograph is under exposed.', '2016-01-28 13:10:03.000000', NULL, 1),
(7432654, 1174673, 181814, '<td valign="top">I think the lighting is harsh creating the blown out areas on the strands of the rope. I am not a fan of the attempt to make this into an abstract and the composition could be better in my opinion.</td>', 'I think the lighting is harsh creating the blown out areas on the strands of the rope. I am not a fan of the attempt to make this into an abstract and the composition could be better in my opinion.', '2016-01-28 13:13:08.000000', NULL, 1),
(7432655, 1174726, 181814, '<td valign="top">I would rather see a well defined piece of rope that the abstract appearance.</td>', 'I would rather see a well defined piece of rope that the abstract appearance.', '2016-01-28 13:14:45.000000', NULL, 1),
(7432657, 1174690, 181814, '<td valign="top">I don''t care much for the cardboard boxes on each side of the rope and the lighting is a little harsh.</td>', 'I don''t care much for the cardboard boxes on each side of the rope and the lighting is a little harsh.', '2016-01-28 13:15:58.000000', NULL, 1),
(7432658, 1174666, 181814, '<td valign="top">I would imagine it is hard to photograph nylon rope without blowing out the highlights as you did here,also what I thing is supposed to be a white background does not show-up on my calibrated screen as white. I don''t like that there are black and white specks on the background that could could be edited out, the hars shadows around the rope is also a bit distracting.</td>', 'I would imagine it is hard to photograph nylon rope without blowing out the highlights as you did here,also what I thing is supposed to be a white background does not show-up on my calibrated screen as white. I don''t like that there are black and white specks on the background that could could be edited out, the hars shadows around the rope is also a bit distracting.', '2016-01-28 13:20:04.000000', NULL, 1),
(7432659, 1174462, 181814, '<td valign="top">The overall photograph looks a little soft, and I think if you had used a polarizing filter you could have eliminated some of the glare off the water creating richer colors throughout.</td>', 'The overall photograph looks a little soft, and I think if you had used a polarizing filter you could have eliminated some of the glare off the water creating richer colors throughout.', '2016-01-28 13:23:37.000000', NULL, 1),
(7432660, 1174650, 181814, '<td valign="top">Very simple but looks nice.</td>', 'Very simple but looks nice.', '2016-01-28 13:24:19.000000', NULL, 1),
(7432661, 1174674, 181814, '<td valign="top">I like the country theme, nice focus, there are some dust spots on the boots that could have been edited out to make it look even better. Nice composition.</td>', 'I like the country theme, nice focus, there are some dust spots on the boots that could have been edited out to make it look even better. Nice composition.', '2016-01-28 13:26:33.000000', NULL, 1),
(7432662, 1174715, 181814, '<td valign="top">I think it is a little over processed creating a few blown out highlights but I do like it.</td>', 'I think it is a little over processed creating a few blown out highlights but I do like it.', '2016-01-28 13:27:43.000000', NULL, 1),
