(7434142, 1174692, 156466, '<td valign="top">Constructive criticism (no vote) - get your lines straight (no pun intended), check your focus, and clean up those sensor spots.</td>', 'Constructive criticism (no vote) - get your lines straight (no pun intended), check your focus, and clean up those sensor spots.', '2016-02-02 08:10:45.000000', NULL, 1),
(7434143, 1174564, 156466, '<td valign="top">Just a little too high key for me, even after recalibrating my monitor.  Really like it, but my 6 would have been 8 if I didn''t lose details in the highlights on the rope.</td>', 'Just a little too high key for me, even after recalibrating my monitor.  Really like it, but my 6 would have been 8 if I didn''t lose details in the highlights on the rope.', '2016-02-02 08:12:00.000000', NULL, 1),
(7434144, 1174599, 156466, '<td valign="top">Like the composition and the OOF background, but I find the front loop lack of focus distracting.</td>', 'Like the composition and the OOF background, but I find the front loop lack of focus distracting.', '2016-02-02 08:13:59.000000', NULL, 1),
(7434162, 1174693, 156466, '<td valign="top">Nope</td>', 'Nope', '2016-02-02 09:41:01.000000', NULL, 1),
(7434163, 1174689, 156466, '<td valign="top">I like the shot and composition, I just wish the rope looked more like a rope and less of a string as it reaches the bottom of the frame.</td>', 'I like the shot and composition, I just wish the rope looked more like a rope and less of a string as it reaches the bottom of the frame.', '2016-02-02 09:42:25.000000', NULL, 1),
(7434164, 1174716, 156466, '<td valign="top">The drop, unfortunately, gets lost in this.</td>', 'The drop, unfortunately, gets lost in this.', '2016-02-02 09:44:48.000000', NULL, 1),
(7434165, 1174477, 156466, '<td valign="top">Interesting composition.  I wish something led my eye to the rope instead of my having to actively look for it.</td>', 'Interesting composition.  I wish something led my eye to the rope instead of my having to actively look for it.', '2016-02-02 09:46:03.000000', NULL, 1),
(7434166, 1174720, 156466, '<td valign="top">The path the rope makes along the ice is both very interesting and very distracting. It appears like a processing artifact at first.  I find myself wishing it was either featured more or not there because as a part of the composition it pulls my eye away.</td>', 'The path the rope makes along the ice is both very interesting and very distracting. It appears like a processing artifact at first.  I find myself wishing it was either featured more or not there because as a part of the composition it pulls my eye away.', '2016-02-02 09:49:55.000000', NULL, 1),
(7434168, 1174505, 156466, '<td valign="top">Best of the bunch for me.</td>', 'Best of the bunch for me.', '2016-02-02 09:51:03.000000', NULL, 1),
